-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g7-st1-2026.1', 7, 'g7_st1', 'Lớp 7 - Trạm 1: Quang hợp và dinh dưỡng thực vật', 'draft', 'Nội dung soạn theo các Bài 21–24, 29–30, 32 của SGK KHTN 7 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st1', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Phân biệt trao đổi chất với chuyển hoá năng lượng và nêu vai trò của chúng.', '{"question":"Quá trình nào là một biểu hiện của trao đổi chất ở cây?","options":["Rễ hấp thụ nước từ đất","Lá đổi hướng do gió","Thân cao thêm do đo bằng thước","Lá rung khi chạm vào"],"hint":"Xét sự lấy chất từ môi trường."}'::jsonb, '{"value":"Rễ hấp thụ nước từ đất","explanation":"Rễ lấy nước từ đất là một phần của quá trình trao đổi chất."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 21. Khái quát về trao đổi chất và chuyển hoá năng lượng"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st1', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Phân biệt trao đổi chất với chuyển hoá năng lượng và nêu vai trò của chúng.', '{"leftItems":["Trao đổi chất","Chuyển hoá năng lượng","Quang hợp"],"rightItems":["Biến quang năng thành hoá năng","Biến đổi năng lượng từ dạng này sang dạng khác","Lấy, biến đổi và thải các chất"],"hint":"Dựa vào nội dung của ải 1."}'::jsonb, '{"value":[{"left":"Trao đổi chất","right":"Lấy, biến đổi và thải các chất"},{"left":"Chuyển hoá năng lượng","right":"Biến đổi năng lượng từ dạng này sang dạng khác"},{"left":"Quang hợp","right":"Biến quang năng thành hoá năng"}],"explanation":"Trao đổi chất: Lấy, biến đổi và thải các chất; Chuyển hoá năng lượng: Biến đổi năng lượng từ dạng này sang dạng khác; Quang hợp: Biến quang năng thành hoá năng."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 21. Khái quát về trao đổi chất và chuyển hoá năng lượng"}]'::jsonb);
