  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st1', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Vận dụng kiến thức trao đổi nước để tưới và bón phân hợp lí cho cây.', '{"textWithBlanks":"Khi tưới cây cần cân nhắc nhu cầu của cây và độ [blank] của đất.","bankWords":["ẩm","cứng","mặn luôn luôn"],"hint":"Dựa vào nội dung của ải 10."}'::jsonb, '{"value":"ẩm","explanation":"Từ đúng là “ẩm”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 30. Trao đổi nước và chất dinh dưỡng ở thực vật; Bài 32. Thực hành: Chứng minh thân vận chuyển nước và lá thoát hơi nước"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
